		if err = randomize.Struct(seed, x, horarioPontoDBTypes, false, strmangle.SetComplement(horarioPontoPrimaryKeyColumns, horarioPontoColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
